  [T('Describing people',`<p>${en('tall')} grand · ${en('short')} petit · ${en('long hair')} cheveux longs · ${en('short hair')} cheveux courts · ${en('blond')} blond · ${en('brown eyes')} yeux marron · ${en('glasses')} lunettes</p><p>${en('He has got glasses.')} · ${en('She is short.')}</p>`)],
